const svg=$('#mk-svg'), out=$('#mk-out');
const spr=$('#mk-spr'), sprL=$('#mk-spr-lbl'), pw=$('#mk-p'), pwL=$('#mk-p-lbl');
const W=640;
const srcPos=[1,2.4,3.6], srcMass=[0.5,0.3,0.2];
const tgtMass=[0.2,0.5,0.3];
function X(v){ return 60 + v*(W-120)/5; }
function render(){
  svg.innerHTML='';
  const spread=+spr.value, p=+pw.value;
  sprL.textContent='target spread = '+spread.toFixed(1);
  pwL.textContent='cost exponent p = '+p.toFixed(0);
  const center=2.5;
  const tgtPos=[center-spread, center, center+spread];
  let i=0,j=0, ri=srcMass[0], rj=tgtMass[0], cost=0; const arcs=[];
  while(i<3 && j<3){
    const m=Math.min(ri,rj);
    cost += m*Math.pow(Math.abs(srcPos[i]-tgtPos[j]),p);
    arcs.push([i,j,m]);
    ri-=m; rj-=m;
    if(ri<=1e-9){ i++; ri=srcMass[i]||0; }
    if(rj<=1e-9){ j++; rj=tgtMass[j]||0; }
  }
  const ySrc=70, yTgt=200, mid=(ySrc+yTgt)/2;
  for(const a of arcs){
    const sx=X(srcPos[a[0]]), tx=X(tgtPos[a[1]]);
    svg.appendChild(SVG('path',{d:'M'+sx+' '+(ySrc+10)+' C '+sx+' '+mid+' '+tx+' '+mid+' '+tx+' '+(yTgt-10),
      fill:'none', stroke:'var(--cyan)','stroke-width':Math.max(1,a[2]*26),'stroke-opacity':0.5}));
  }
  for(let k=0;k<3;k++) svg.appendChild(SVG('circle',{cx:X(srcPos[k]),cy:ySrc,r:6+srcMass[k]*30,fill:'var(--yellow)'}));
  for(let k=0;k<3;k++) svg.appendChild(SVG('circle',{cx:X(tgtPos[k]),cy:yTgt,r:6+tgtMass[k]*30,fill:'var(--violet)'}));
  const lab=function(x,y,t,c){const e=SVG('text',{x:x,y:y,'text-anchor':'middle','font-size':13,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(30,ySrc+5,'μ','var(--yellow)'); lab(30,yTgt+5,'ν','var(--violet)');
  out.textContent='source masses μ = (0.5, 0.3, 0.2);   target masses ν = (0.2, 0.5, 0.3)\n'
    +'optimal monotone (north-west-corner) plan uses '+arcs.length+' arcs — some source piles split across several targets, which no Monge map could do\n'
    +'total cost  Σ πᵢⱼ |xᵢ−yⱼ|^p = '+cost.toFixed(3)+'   (p = '+p.toFixed(0)+')';
}
spr.addEventListener('input',render); pw.addEventListener('input',render); render();

const PX0=54, PX1=474, SY=86, TY=214;
const dOf = px => (px-PX0)/(PX1-PX0)*10;   // pixel -> data
function draw(){
  G.innerHTML='';
  // guide rails
  G.appendChild(SVG('line',{x1:PX0,y1:SY,x2:PX1,y2:SY,stroke:'var(--line)','stroke-width':1.5}));
  G.appendChild(SVG('line',{x1:PX0,y1:TY,x2:PX1,y2:TY,stroke:'var(--line)','stroke-width':1.5}));
  var sl=SVG('text',{x:PX0-8,y:SY+4,'font-size':11,fill:'var(--pink)','text-anchor':'end','pointer-events':'none'}); sl.textContent='source \u03bc'; G.appendChild(sl);
  var tl=SVG('text',{x:PX0-8,y:TY+4,'font-size':11,fill:'var(--cyan)','text-anchor':'end','pointer-events':'none'}); tl.textContent='target \u03bd'; G.appendChild(tl);
  // sorted (= optimal monotone) matching
  var S=pts.filter(function(p){return p.id.charAt(0)==='s';}).slice().sort(function(a,b){return a.x-b.x;});
  var T=pts.filter(function(p){return p.id.charAt(0)==='t';}).slice().sort(function(a,b){return a.x-b.x;});
  var w1=0,w2=0;
  for(var k=0;k<S.length;k++){ var dx=dOf(S[k].x)-dOf(T[k].x); w1+=Math.abs(dx); w2+=dx*dx;
    G.appendChild(SVG('line',{x1:S[k].x,y1:SY,x2:T[k].x,y2:TY,stroke:'var(--violet)','stroke-width':2,'stroke-opacity':0.8,'pointer-events':'none'})); }
  w1/=S.length; w2=Math.sqrt(w2/S.length);
  out.innerHTML='optimal plan = <b>monotone</b> (k-th smallest source \u2192 k-th smallest target) &nbsp;\u00b7&nbsp; mean cost $W_1$=<b>'+w1.toFixed(2)+'</b>, $W_2$=<b>'+w2.toFixed(2)+'</b> &nbsp;\u00b7&nbsp; <span style=\"color:var(--mute)\">drag any <span style=\"color:var(--pink)\">source</span> or <span style=\"color:var(--cyan)\">target</span> mass along its rail. For a <b>convex</b> cost on the line the optimal coupling is the sorted one \u2014 the matching lines <b>never cross</b>; a crossing can always be uncrossed without raising the cost (strictly lowering it for a strictly convex cost like $W_2$).</span>';
  if(window.renderMathInElement) try{ renderMathInElement(out,{throwOnError:false,delimiters:[{left:'$',right:'$',display:false}]}); }catch(e){}
}

const svg=$('#du-svg'), out=$('#du-out');
const mv=$('#du-m'), mL=$('#du-m-lbl');
const W=640;
function render(){
  svg.innerHTML='';
  const shift=+mv.value; mL.textContent='shift of ν = '+shift.toFixed(1);
  const muAt=[[1,0.5],[2,0.5]];
  const nuAt=[[3+shift,0.5],[4+shift,0.5]];
  const xmin=-0.5, xmax=7.5, baseY=210, topY=40;
  const PX=function(x){ return 50 + (x-xmin)*(W-80)/(xmax-xmin); };
  const PY=function(c){ return baseY - c*(baseY-topY); };
  const cdf=function(at,x){ let s=0; for(const a of at) if(a[0]<=x) s+=a[1]; return s; };
  let area=0; const N=600, dx=(xmax-xmin)/N;
  let pathMu='', pathNu='', fill='';
  for(let k=0;k<=N;k++){ const x=xmin+k*dx; const fm=cdf(muAt,x), fn=cdf(nuAt,x); area+=Math.abs(fm-fn)*dx;
    pathMu+=(k?'L':'M')+PX(x)+' '+PY(fm)+' ';
    pathNu+=(k?'L':'M')+PX(x)+' '+PY(fn)+' ';
    fill+=(k?'L':'M')+PX(x)+' '+PY(fm)+' ';
  }
  for(let k=N;k>=0;k--){ const x=xmin+k*dx; fill+='L'+PX(x)+' '+PY(cdf(nuAt,x))+' '; }
  fill+='Z';
  svg.appendChild(SVG('path',{d:fill,fill:'var(--cyan)','fill-opacity':0.16,stroke:'none'}));
  svg.appendChild(SVG('line',{x1:PX(xmin),y1:baseY,x2:PX(xmax),y2:baseY,stroke:'var(--line)'}));
  svg.appendChild(SVG('path',{d:pathMu,fill:'none',stroke:'var(--yellow)','stroke-width':2}));
  svg.appendChild(SVG('path',{d:pathNu,fill:'none',stroke:'var(--violet)','stroke-width':2}));
  const lab=function(x,y,t,c){const e=SVG('text',{x:x,y:y,'font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(PX(0.6),topY-4,'Fμ','var(--yellow)'); lab(PX(4.4+shift),topY+14,'Fν','var(--violet)');
  out.textContent='Kantorovich–Rubinstein (1D):  W₁(μ,ν) = ∫ |Fμ(x) − Fν(x)| dx  =  shaded area between the CDFs\n'
    +'W₁ = '+area.toFixed(3)+'\n'
    +'the optimal 1-Lipschitz potential has f′(x) = sign(Fν−Fμ) ∈ {−1,+1} and attains the sup ∫ f d(μ−ν) = W₁.';
}
mv.addEventListener('input',render); render();

const svg=$('#wa-svg'), out=$('#wa-out');
const mv=$('#wa-m'), mL=$('#wa-m-lbl'), sv=$('#wa-s'), sL=$('#wa-s-lbl');
const W=640;
function render(){
  svg.innerHTML='';
  const m=+mv.value, s=+sv.value;
  mL.textContent='ν mean m = '+m.toFixed(1); sL.textContent='ν std σ = '+s.toFixed(2);
  const xmin=-6, xmax=8, baseY=210;
  const PX=function(x){ return 40+(x-xmin)*(W-60)/(xmax-xmin); };
  const g=function(x,mu,si){ return Math.exp(-(x-mu)*(x-mu)/(2*si*si))/(si*Math.sqrt(2*Math.PI)); };
  const scale=150/g(0,0,1); const PY=function(v){ return baseY - v*scale; };
  let p1='', p2=''; const N=400, dx=(xmax-xmin)/N;
  for(let k=0;k<=N;k++){ const x=xmin+k*dx; p1+=(k?'L':'M')+PX(x)+' '+PY(g(x,0,1))+' '; p2+=(k?'L':'M')+PX(x)+' '+PY(g(x,m,s))+' '; }
  svg.appendChild(SVG('line',{x1:PX(xmin),y1:baseY,x2:PX(xmax),y2:baseY,stroke:'var(--line)'}));
  svg.appendChild(SVG('path',{d:p1,fill:'none',stroke:'var(--yellow)','stroke-width':2}));
  svg.appendChild(SVG('path',{d:p2,fill:'none',stroke:'var(--violet)','stroke-width':2}));
  const lab=function(x,y,t,c){const e=SVG('text',{x:x,y:y,'font-size':12,fill:c});e.textContent=t;svg.appendChild(e);};
  lab(PX(0)-26,40,'μ=N(0,1)','var(--yellow)'); lab(PX(m)-24,56,'ν','var(--violet)');
  const w2sq=m*m+(s-1)*(s-1), w2=Math.sqrt(w2sq);
  out.textContent='μ = N(0,1)  (yellow),   ν = N('+m.toFixed(1)+', '+(s*s).toFixed(2)+')  (violet)\n'
    +'closed form  W₂² = |m₁−m₂|² + (σ₁−σ₂)² = '+(m*m).toFixed(2)+' + '+((s-1)*(s-1)).toFixed(2)+' = '+w2sq.toFixed(3)+'\n'
    +'W₂(μ,ν) = '+w2.toFixed(3)+'   — a true metric (≥0, =0 iff μ=ν, triangle inequality); unlike TV it sees how far the mass must travel.';
}
mv.addEventListener('input',render); sv.addEventListener('input',render); render();

const svg=$('#br-svg'), out=$('#br-out');
const cv=$('#br-c'), cL=$('#br-c-lbl'), mcv=$('#br-mc'), mcL=$('#br-mc-lbl');
function render(){
  svg.innerHTML='';
  const c=+cv.value, Mc=+mcv.value;
  cL.textContent='breakpoint c = '+c.toFixed(2);
  mcL.textContent='target mass on [0,c] = '+Mc.toFixed(2);
  const h1=Mc/c, h2=(1-Mc)/(1-c);
  const T=function(x){ return x<=Mc ? c*x/Mc : c+(x-Mc)*(1-c)/(1-Mc); };
  const ox=70, oy=40, sz=200;
  const PXx=function(x){ return ox+x*sz; }, PYy=function(y){ return oy+sz-y*sz; };
  svg.appendChild(SVG('rect',{x:ox,y:oy,width:sz,height:sz,fill:'none',stroke:'var(--line)'}));
  svg.appendChild(SVG('path',{d:'M'+PXx(0)+' '+PYy(0)+' L '+PXx(1)+' '+PYy(1),stroke:'var(--mute)','stroke-dasharray':'4 4',fill:'none'}));
  let pm=''; const N=200; for(let k=0;k<=N;k++){ const x=k/N; pm+=(k?'L':'M')+PXx(x)+' '+PYy(T(x))+' '; }
  svg.appendChild(SVG('path',{d:pm,fill:'none',stroke:'var(--cyan)','stroke-width':2.5}));
  const lab=function(x,y,t,c2,anc){const e=SVG('text',{x:x,y:y,'text-anchor':anc||'middle','font-size':12,fill:c2});e.textContent=t;svg.appendChild(e);};
  lab(ox+sz/2,oy+sz+30,'x   (μ = Unif[0,1])','var(--mute)');
  lab(ox-46,oy+sz/2,'T(x)','var(--cyan)');
  const ox2=ox+sz+110, sz2=200, denScale=70;
  const Ty=function(v){ return oy+sz - v*denScale; };
  svg.appendChild(SVG('line',{x1:ox2,y1:oy+sz,x2:ox2+sz2,y2:oy+sz,stroke:'var(--line)'}));
  svg.appendChild(SVG('rect',{x:ox2,y:Ty(h1),width:c*sz2,height:(oy+sz)-Ty(h1),fill:'var(--violet)','fill-opacity':0.4}));
  svg.appendChild(SVG('rect',{x:ox2+c*sz2,y:Ty(h2),width:(1-c)*sz2,height:(oy+sz)-Ty(h2),fill:'var(--violet)','fill-opacity':0.4}));
  lab(ox2+sz2/2,oy+sz+30,'y   (target density ν)','var(--mute)');
  out.textContent='source μ = Unif[0,1];   target ν = step density (height '+h1.toFixed(2)+' on [0,'+c.toFixed(2)+'], '+h2.toFixed(2)+' on ['+c.toFixed(2)+',1])\n'
    +'Brenier map  T = Fν⁻¹∘Fμ  (cyan) is monotone increasing — the gradient of a convex φ — with a kink where the target density jumps\n'
    +'slope T′ = ρμ/ρν: where ν is dense T compresses, where ν is sparse T stretches (the 1-D Monge–Ampère relation).';
}
cv.addEventListener('input',render); mcv.addEventListener('input',render); render();

const svg=$('#ge-svg'), out=$('#ge-out');
const tv=$('#ge-t'), tL=$('#ge-t-lbl');
const W=640;
function render(){
  svg.innerHTML='';
  const t=+tv.value; tL.textContent='t = '+t.toFixed(2);
  const m0=-3, m1=3, sig=0.7, xmin=-6, xmax=6, baseY=210;
  const PX=function(x){ return 40+(x-xmin)*(W-60)/(xmax-xmin); };
  const g=function(x,mu,si){ return Math.exp(-(x-mu)*(x-mu)/(2*si*si))/(si*Math.sqrt(2*Math.PI)); };
  const scale=120/g(0,0,sig); const PY=function(v){ return baseY-v*scale; };
  const curve=function(f){ let p=''; const N=400, dx=(xmax-xmin)/N; for(let k=0;k<=N;k++){ const x=xmin+k*dx; p+=(k?'L':'M')+PX(x)+' '+PY(f(x))+' '; } return p; };
  const md=(1-t)*m0+t*m1;
  svg.appendChild(SVG('line',{x1:PX(xmin),y1:baseY,x2:PX(xmax),y2:baseY,stroke:'var(--line)'}));
  svg.appendChild(SVG('path',{d:curve(function(x){return g(x,m0,sig);}),fill:'none',stroke:'var(--mute)','stroke-width':1,'stroke-dasharray':'3 3'}));
  svg.appendChild(SVG('path',{d:curve(function(x){return g(x,m1,sig);}),fill:'none',stroke:'var(--mute)','stroke-width':1,'stroke-dasharray':'3 3'}));
  svg.appendChild(SVG('path',{d:curve(function(x){return (1-t)*g(x,m0,sig)+t*g(x,m1,sig);}),fill:'none',stroke:'var(--pink)','stroke-width':2}));
  svg.appendChild(SVG('path',{d:curve(function(x){return g(x,md,sig);}),fill:'none',stroke:'var(--cyan)','stroke-width':2.5}));
  const lab=function(x,y,t2,c){const e=SVG('text',{x:x,y:y,'font-size':12,fill:c});e.textContent=t2;svg.appendChild(e);};
  lab(PX(-5.6),34,'cyan: displacement geodesic μ_t (slides)','var(--cyan)');
  lab(PX(-5.6),50,'pink: linear interpolation (1−t)μ+tν (fades)','var(--pink)');
  out.textContent='endpoints  μ = N(−3, '+(sig*sig).toFixed(2)+'),  ν = N(3, '+(sig*sig).toFixed(2)+')\n'
    +'W₂ displacement geodesic: one bump of constant shape centred at (1−t)(−3)+t(3) = '+md.toFixed(2)+' — the true geodesic\n'
    +'linear interpolation grows a second bump; it is NOT a W₂ geodesic (its W₂ length strictly exceeds W₂(μ,ν)).';
}
tv.addEventListener('input',render); render();

const svg=$('#fl-svg'), out=$('#fl-out');
const tv=$('#fl-t'), tL=$('#fl-t-lbl');
const W=640;
function render(){
  svg.innerHTML='';
  const t=+tv.value; tL.textContent='time t = '+t.toFixed(2);
  const m0=3.0, s0=0.5;
  const mt=m0*Math.exp(-t);
  const vt=s0*s0*Math.exp(-2*t)+(1-Math.exp(-2*t));
  const st=Math.sqrt(vt);
  const xmin=-5, xmax=6, baseY=205;
  const PX=function(x){ return 40+(x-xmin)*(W-60)/(xmax-xmin); };
  const g=function(x,mu,si){ return Math.exp(-(x-mu)*(x-mu)/(2*si*si))/(si*Math.sqrt(2*Math.PI)); };
  const scale=120/g(0,0,0.5); const PY=function(v){ return baseY-v*scale; };
  const curve=function(mu,si){ let p=''; const N=400, dx=(xmax-xmin)/N; for(let k=0;k<=N;k++){ const x=xmin+k*dx; p+=(k?'L':'M')+PX(x)+' '+PY(g(x,mu,si))+' '; } return p; };
  svg.appendChild(SVG('line',{x1:PX(xmin),y1:baseY,x2:PX(xmax),y2:baseY,stroke:'var(--line)'}));
  svg.appendChild(SVG('path',{d:curve(0,1),fill:'none',stroke:'var(--mute)','stroke-width':1.5,'stroke-dasharray':'4 4'}));
  svg.appendChild(SVG('path',{d:curve(mt,st),fill:'none',stroke:'var(--cyan)','stroke-width':2.5}));
  const lab=function(x,y,t2,c){const e=SVG('text',{x:x,y:y,'font-size':12,fill:c});e.textContent=t2;svg.appendChild(e);};
  lab(PX(-4.7),34,'cyan: ρ_t  (Fokker–Planck flow)','var(--cyan)');
  lab(PX(-4.7),50,'dashed: Gibbs equilibrium ρ∞ ∝ e^(−V)','var(--mute)');
  const KL=0.5*(vt+mt*mt-1-Math.log(vt));
  out.textContent='Fokker–Planck  ∂_tρ = Δρ + ∇·(ρ∇V),  V(x)=x²/2  —  the W₂ gradient flow of free energy F(ρ)=∫ρ log ρ + ∫Vρ\n'
    +'start ρ₀ = N(3, 0.25);   ρ_t = N('+mt.toFixed(2)+', '+vt.toFixed(2)+')  converging to the Gibbs measure N(0,1)\n'
    +'free-energy gap  F(ρ_t)−F(ρ∞) = KL(ρ_t‖ρ∞) = '+KL.toFixed(3)+'  — decreasing monotonically to 0 (steepest descent in W₂).';
}
tv.addEventListener('input',render); render();
